import{_ as a,o as s,c as n,a2 as e}from"./chunks/framework.CvydjLy7.js";const h=JSON.parse('{"title":"五、JSON 序列化","description":"","frontmatter":{"title":"五、JSON 序列化"},"headers":[{"level":3,"title":"5.1 默认行为","slug":"_5-1-默认行为","link":"#_5-1-默认行为","children":[]},{"level":3,"title":"5.2 常用配置项","slug":"_5-2-常用配置项","link":"#_5-2-常用配置项","children":[]},{"level":3,"title":"5.3 常用注解","slug":"_5-3-常用注解","link":"#_5-3-常用注解","children":[]}],"relativePath":"ch03/05.md","filePath":"ch03/05.md","lastUpdated":1789497795000}'),o={name:"ch03/05.md"};function d(p,t,i,l,c,r){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="五、json-序列化" tabindex="-1">五、JSON 序列化 <a class="header-anchor" href="#五、json-序列化" aria-label="Permalink to &quot;五、JSON 序列化&quot;">​</a></h1><h3 id="_5-1-默认行为" tabindex="-1">5.1 默认行为 <a class="header-anchor" href="#_5-1-默认行为" aria-label="Permalink to &quot;5.1 默认行为&quot;">​</a></h3><p>引入 Web starter 后，Jackson 3 自动配置好，控制器返回的对象会被自动序列化为 JSON。案例工程的响应体长这样：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:8080/api/activities?size=1&quot;</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;code&quot;: 0,</span></span>
<span class="line"><span>  &quot;message&quot;: &quot;success&quot;,</span></span>
<span class="line"><span>  &quot;data&quot;: {</span></span>
<span class="line"><span>    &quot;items&quot;: [</span></span>
<span class="line"><span>      {</span></span>
<span class="line"><span>        &quot;id&quot;: 5,</span></span>
<span class="line"><span>        &quot;title&quot;: &quot;Spring Boot 官方文档（online）&quot;,</span></span>
<span class="line"><span>        &quot;description&quot;: &quot;官方参考文档入口，版本随官方发布同步更新。&quot;,</span></span>
<span class="line"><span>        &quot;venueId&quot;: 5,</span></span>
<span class="line"><span>        &quot;venueName&quot;: &quot;大学生活动中心&quot;,</span></span>
<span class="line"><span>        &quot;type&quot;: &quot;LINK&quot;,</span></span>
<span class="line"><span>        &quot;typeLabel&quot;: &quot;活动详情页&quot;,</span></span>
<span class="line"><span>        &quot;url&quot;: &quot;https://docs.spring.io/spring-boot/&quot;,</span></span>
<span class="line"><span>        &quot;fileSizeText&quot;: &quot;-&quot;,</span></span>
<span class="line"><span>        &quot;approvedCount&quot;: 312,</span></span>
<span class="line"><span>        &quot;organizer&quot;: &quot;陶老师&quot;,</span></span>
<span class="line"><span>        &quot;tags&quot;: &quot;官方文档,参考&quot;,</span></span>
<span class="line"><span>        &quot;createdAt&quot;: &quot;2026-08-20 08:00:00&quot;,</span></span>
<span class="line"><span>        &quot;updatedAt&quot;: &quot;2026-08-20 08:00:00&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;page&quot;: 0,</span></span>
<span class="line"><span>    &quot;size&quot;: 1,</span></span>
<span class="line"><span>    &quot;total&quot;: 5,</span></span>
<span class="line"><span>    &quot;totalPages&quot;: 5</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这份响应里有几处值得留意的设计：</p><table tabindex="0"><thead><tr><th>现象</th><th>背后的处理</th></tr></thead><tbody><tr><td>没有出现任何 <code>null</code> 字段</td><td><code>default-property-inclusion: non_null</code> 生效，响应体更干净</td></tr><tr><td><code>createdAt</code> 是 <code>&quot;2026-08-20 08:00:00&quot;</code> 而不是带 <code>T</code> 的 ISO 格式</td><td>字段上加了 <code>@JsonFormat</code>，因为 <code>date-format</code> 对 <code>LocalDateTime</code> 无效</td></tr><tr><td>既有 <code>type</code> 又有 <code>typeLabel</code></td><td>枚举值给程序判断，中文标签给界面展示</td></tr><tr><td><code>fileSizeText</code> 是 <code>&quot;-&quot;</code> 而不是数字</td><td>活动详情页型活动没有文件大小，DTO 里做了展示层的格式化</td></tr></tbody></table><h3 id="_5-2-常用配置项" tabindex="-1">5.2 常用配置项 <a class="header-anchor" href="#_5-2-常用配置项" aria-label="Permalink to &quot;5.2 常用配置项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>作用</th><th>本案例是否使用</th></tr></thead><tbody><tr><td><code>spring.jackson.default-property-inclusion</code></td><td>控制值为 null 的字段是否输出</td><td>用了 <code>non_null</code></td></tr><tr><td><code>spring.jackson.property-naming-strategy</code></td><td>字段命名策略（如转下划线）</td><td>未用，保持驼峰</td></tr><tr><td><code>spring.jackson.date-format</code></td><td>日期格式</td><td><strong>不用</strong>，对 JSR-310 类型无效</td></tr><tr><td><code>spring.jackson.deserialization.fail-on-unknown-properties</code></td><td>未知字段是否报错</td><td>未用，默认忽略</td></tr></tbody></table><blockquote><p><strong>三个 4.x 特有的坑</strong></p><p>**坑一：<code>write-dates-as-timestamps</code> 会导致启动失败。**该枚举已从 <code>SerializationFeature</code> 移到 <code>DateTimeFeature</code>，而 Spring Boot 4.1 的 <code>JacksonProperties</code> 没暴露这个配置项。写了就报 <code>No enum constant tools.jackson.databind.SerializationFeature.write-dates-as-timestamps</code>。删掉即可，Jackson 3 默认输出 ISO-8601。</p><p>**坑二：<code>date-format</code> 对 <code>LocalDateTime</code> 无效。**它只作用于 <code>java.util.Date</code>。JSR-310 类型的格式必须在字段上用 <code>@JsonFormat</code>：</p><p><strong>正确做法</strong></p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">JsonFormat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pattern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;yyyy-MM-dd HH:mm:ss&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LocalDateTime createdAt;</span></span></code></pre></div><p>**坑三：<code>ObjectMapper</code> 换包了。**手写 Jackson 配置代码时，import 要从 <code>com.fasterxml.jackson.databind</code> 改成 <code>tools.jackson.databind</code>。注解包 <code>com.fasterxml.jackson.annotation</code> 不变。</p></blockquote><h3 id="_5-3-常用注解" tabindex="-1">5.3 常用注解 <a class="header-anchor" href="#_5-3-常用注解" aria-label="Permalink to &quot;5.3 常用注解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>注解</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>@JsonFormat</code></td><td>指定日期时间格式</td><td><code>@JsonFormat(pattern = &quot;yyyy-MM-dd HH:mm:ss&quot;)</code></td></tr><tr><td><code>@JsonProperty</code></td><td>指定 JSON 字段名（3.x 中包名不变）</td><td><code>@JsonProperty(&quot;approved_count&quot;)</code></td></tr><tr><td><code>@JsonIgnore</code></td><td>序列化与反序列化都忽略</td><td>敏感字段</td></tr><tr><td><code>@JsonInclude</code></td><td>字段级控制空值输出</td><td><code>@JsonInclude(NON_NULL)</code></td></tr><tr><td><code>@JsonIgnoreProperties</code></td><td>忽略未知字段</td><td><code>ignoreUnknown = true</code></td></tr></tbody></table>`,12)])])}const q=a(o,[["render",d]]);export{h as __pageData,q as default};
